package org.humanjourney.core.advancement;
import java.util.*;
import java.util.function.Predicate;
import com.google.gson.*;
import org.humanjourney.core.progress.ProgressJson;
/** Presentation only. References existing advancements, never criteria/scores/prerequisites. */
public record NativePresentation(int schema_version,List<Tab> tabs) {
 public static final int MAX_JSON=512*1024,MAX_TABS=8,MAX_IDS=512,MAX_LINKS=2048,MAX_REGIONS=32;
 public record Point(int x,int y){}
 public record Position(String advancement,int x,int y){}
 public record Link(String from,String to,List<Point> route){public Link{route=List.copyOf(route);}}
 public record Region(String id,String title,int x,int y,int width,int height,int color,int border,String texture,Integer tint,List<String> members){public Region{members=List.copyOf(members);}}
 public record Tab(String root,List<Position> positions,List<Link> connections,List<Region> eras){public Tab{positions=List.copyOf(positions);connections=List.copyOf(connections);eras=List.copyOf(eras);}public Set<String> ids(){var ids=new HashSet<String>();ids.add(root);positions.forEach(p->ids.add(p.advancement));connections.forEach(e->{ids.add(e.from);ids.add(e.to);});eras.forEach(e->ids.addAll(e.members));return Set.copyOf(ids);}}
 public NativePresentation{tabs=List.copyOf(tabs);}
 public static NativePresentation empty(){return new NativePresentation(1,List.of());}
 public String json(){return new Gson().toJson(this);}
 public static NativePresentation read(String json,Predicate<String> exists){ProgressJson.bounded(json,1024*1024);return parse(JsonParser.parseString(json),exists);}
 static void need(boolean b,String error){if(!b)throw new IllegalArgumentException(error);}
 static JsonObject obj(JsonElement e){need(e!=null&&e.isJsonObject(),"expected presentation object");return e.getAsJsonObject();}
 static void keys(JsonObject o,String...allowed){var set=Set.of(allowed);for(String k:o.keySet())need(set.contains(k),"unknown presentation field "+k);}
 static JsonArray list(JsonObject o,String k,int max){if(!o.has(k))return new JsonArray();var e=o.get(k);need(e.isJsonArray()&&e.getAsJsonArray().size()<=max,"invalid "+k+" count; limit "+max);return e.getAsJsonArray();}
 static String text(JsonObject o,String k,int max){var e=o.get(k);need(e!=null&&e.isJsonPrimitive()&&e.getAsJsonPrimitive().isString(),"text required: "+k);String s=e.getAsString();need(!s.isBlank()&&s.length()<=max&&s.chars().noneMatch(c->c<32),"invalid "+k);return s;}
 static String adv(JsonObject o,String k){String s=text(o,k,192);need(s.matches("human_journey:[a-z0-9_./-]+"),"only explicit human_journey advancement IDs supported: "+s);return s;}
 static int number(JsonObject o,String k,int min,int max){var e=o.get(k);need(e!=null&&e.isJsonPrimitive()&&e.getAsJsonPrimitive().isNumber(),"integer required: "+k);try{int n=e.getAsBigDecimal().intValueExact();need(n>=min&&n<=max,k+" outside "+min+".."+max);return n;}catch(ArithmeticException ex){throw new IllegalArgumentException("int32 required: "+k);}}
 static int color(JsonObject o,String k,int fallback){if(!o.has(k))return fallback;var e=o.get(k);if(e.isJsonPrimitive()&&e.getAsJsonPrimitive().isNumber())return number(o,k,0,0xFFFFFF);String s=text(o,k,7);need(s.matches("#[a-fA-F0-9]{6}"),"expected #RRGGBB "+k);return Integer.parseInt(s.substring(1),16);}
 public static NativePresentation parse(JsonElement input,Predicate<String> exists){var o=obj(input);keys(o,"schema_version","tabs");need(number(o,"schema_version",1,1)==1,"unsupported presentation schema");var tabs=new ArrayList<Tab>();var roots=new HashSet<String>();int ids=0,links=0,regions=0;for(var t:list(o,"tabs",MAX_TABS)){var a=obj(t);keys(a,"root","positions","connections","eras");String root=adv(a,"root");need(roots.add(root),"duplicate root "+root);var positions=new ArrayList<Position>();var positioned=new HashSet<String>();for(var e:list(a,"positions",MAX_IDS)){var p=obj(e);keys(p,"advancement","x","y");String id=adv(p,"advancement");need(positioned.add(id),"duplicate position "+id);positions.add(new Position(id,number(p,"x",0,8192),number(p,"y",0,8192)));}var edges=new ArrayList<Link>();var seen=new HashSet<String>();for(var e:list(a,"connections",MAX_LINKS)){var p=obj(e);keys(p,"from","to","route");String from=adv(p,"from"),to=adv(p,"to");need(!from.equals(to),"self connection");String key=from.compareTo(to)<0?from+"|"+to:to+"|"+from;need(seen.add(key),"duplicate physical connection");var route=new ArrayList<Point>();for(var point:list(p,"route",16)){need(point.isJsonObject(),"route point must be {x,y}");var q=obj(point);keys(q,"x","y");route.add(new Point(number(q,"x",0,8192),number(q,"y",0,8192)));}edges.add(new Link(from,to,route));}var areas=new ArrayList<Region>();var eraIds=new HashSet<String>();for(var e:list(a,"eras",MAX_REGIONS)){var p=obj(e);keys(p,"id","title","x","y","width","height","color","border","texture","tint","members");String id=text(p,"id",96);need(id.matches("[a-z0-9_./:-]+")&&eraIds.add(id),"invalid/duplicate Era ID");String texture=null;if(p.has("texture")){texture=text(p,"texture",192);need(!texture.contains("..")&&texture.matches("[a-z0-9_.-]+:textures/[a-z0-9_./-]+\\.png"),"texture must be local namespace:textures/...png");}var members=new ArrayList<String>();for(var m:list(p,"members",MAX_IDS)){var q=new JsonObject();q.add("advancement",m);String member=adv(q,"advancement");need(!members.contains(member),"duplicate Era member");members.add(member);}need(!members.isEmpty(),"Era members required for native visibility");areas.add(new Region(id,text(p,"title",128),number(p,"x",0,8192),number(p,"y",0,8192),number(p,"width",1,8192),number(p,"height",1,8192),color(p,"color",0x202020),color(p,"border",0x808080),texture,p.has("tint")?color(p,"tint",0):null,members));}var tab=new Tab(root,positions,edges,areas);for(String id:tab.ids())need(exists.test(id),"unknown advancement reference "+id);ids+=tab.ids().size();links+=edges.size();regions+=areas.size();need(ids<=MAX_IDS&&links<=MAX_LINKS&&regions<=MAX_REGIONS,"aggregate presentation budget exceeded");tabs.add(tab);}var result=new NativePresentation(1,tabs);need(result.json().getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=1024*1024,"presentation exceeds1MiB wire budget");return result;}
 public NativePresentation visible(Set<String> drawn){var out=new ArrayList<Tab>();for(var t:tabs){if(!drawn.contains(t.root))continue;var areas=new ArrayList<Region>();for(var e:t.eras){var members=e.members.stream().filter(drawn::contains).toList();if(!members.isEmpty())areas.add(new Region(e.id,e.title,e.x,e.y,e.width,e.height,e.color,e.border,e.texture,e.tint,members));}out.add(new Tab(t.root,t.positions.stream().filter(p->drawn.contains(p.advancement)).toList(),t.connections.stream().filter(e->drawn.contains(e.from)&&drawn.contains(e.to)).toList(),areas));}return new NativePresentation(1,out);}
 public record Widget(String id,String parent,int x,int y,boolean visible){}
 public static List<Link> drawable(Tab tab,Map<String,Widget> widgets){return tab.connections.stream().filter(e->{var a=widgets.get(e.from);var b=widgets.get(e.to);return a!=null&&b!=null&&a.visible&&b.visible&&!Objects.equals(a.id,b.parent)&&!Objects.equals(b.id,a.parent);}).toList();}
 public static List<Point> route(Link link,Map<String,Widget> widgets){var a=widgets.get(link.from);var b=widgets.get(link.to);var points=new ArrayList<Point>();points.add(new Point(a.x+13,a.y+13));if(link.route.isEmpty()){int x=(a.x+b.x)/2+13;points.add(new Point(x,a.y+13));points.add(new Point(x,b.y+13));}else points.addAll(link.route);points.add(new Point(b.x+13,b.y+13));return List.copyOf(points);}
}
